insert into question_bank_items (id, stage_id, position, question, hint, answer) values (105, 7, 14, 'איך אתה שומר על סוויטה גדלה תחזוקתית ונמנע מחוב-בדיקות?', 'התייחסו לבדיקות כמוצר עם עלות, לא ארכיון לכתיבה-בלבד.', ARRAY['רכזו נקודות שינוי — page/component objects, fixtures משותפים, מקום אחד ללוקייטורים — כך ששינוי UI נוגע בקובץ אחד, לא בחמישים.', 'גזמו באופן פעיל: מחקו בדיקות כפולות ומיושנות, ולעולם אל תתנו לתיקיית quarantine להפוך לבית קברות. עקבו אחרי שיעור flaky ומשך הסוויטה כמדדים ממדרגה ראשונה.', 'מנעו חוב בזמן הכתיבה עם סקירה ומוסכמות משותפות, ורפקטרו בדיקות כמו קוד פרודקשן. סוויטה שאי אפשר לבטוח בה או להרשות להריץ גרועה מקטנה שאפשר.']::text[]);
insert into question_bank_stages (id, lang, position, icon, title) values (8, 'he', 2, '🧩', 'שלב 3 — קוד ו-API');
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (106, 8, 0, 'הסבר fixtures ב-pytest ואת ה-scope שלהם. מתי תשתמש ב-session fixture?', 'Fixture הוא הזרקת תלויות עם מחזור חיים.', ARRAY['Fixture מספק תלות לבדיקה — לקוח, session של DB, נתונים זרועים — והבדיקה מבקשת אותו על ידי שמו כפרמטר. התלויות מפורשות ולא מוחבאות ב-setup.', '`scope` קובע כל כמה זמן הוא נבנה: function (ברירת מחדל), class, module, package או session.', 'השתמשו ב-session fixture למשהו יקר ולמעשה לקריאה בלבד: דפדפן, טוקן הזדהות, קונטיינר Docker, סכימת DB אחרי מיגרציה.', 'הסכנה היא מצב משותף שניתן לשינוי — session fixture שבדיקות משנות מחזיר בשקט תלות בסדר ההרצה. השתמשו ב-`yield` ל-teardown, והשאירו כל דבר שניתן לכתיבה ב-scope של function.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (107, 8, 1, 'איך תפעיל parametrize כדי להריץ את אותה לוגיקה על קלטים רבים?', 'גוף אחד, קלטים רבים — וכל מקרה חייב להיות מדווח בנפרד.', ARRAY['`@pytest.mark.parametrize("value,expected", [...])` מריץ את הגוף פעם אחת לכל טאפל, וכל מקרה מדווח כבדיקה נפרדת — כך שקלט אחד שנכשל לא מסתיר את השאר.', 'השתמשו ב-`ids=` או בערכים קריאים כדי שהדוח ינקוב בשם המקרה ולא ב"case 7". כשל שאי אפשר לזהות במבט אחד מבטל את התועלת.', 'ערמו דקורטורים למכפלה קרטזית (דפדפנים × תפקידים), או פרמטרו fixture כדי לקבל את אותו אפקט בשכבת ההקמה.', 'אל תבריחו לוגיקה פנימה: אם הערך הצפוי דורש `if` כדי להתחשב, הענף הזה ראוי לבדיקה משלו.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (108, 8, 2, 'איך אתה בודק REST API — קודי סטטוס, סכימה ומקרי קצה שליליים?', 'סטטוס, סכימה, סמנטיקה וכותרות — ורוב הסיכון נמצא במסלולים הלא-מוצלחים.', ARRAY['בדקו את קוד הסטטוס, ואז ולידציה של הגוף מול סכימה (JSON Schema, Pydantic, Zod) כדי ששדה חסר או בלתי צפוי ייכשל בקול ולא יעבור בשקט.', 'בדקו סמנטיקה ולא רק צורה: המשאב שנוצר באמת ניתן לשליפה, סכומי העמודים מסתדרים, חותמות זמן ומטבעות הגיוניים.', 'כסו את המרחב השלילי במכוון — חוסר הרשאה (401), משתמש לא נכון (403), מזהה לא קיים (404), גוף שגוי (400), payload גדול מדי, content type שגוי. שם חיים הבאגים האמיתיים.', 'הוסיפו בדיקות חוזה מול המפרט המפורסם כדי שהשרת והלקוחות שנוצרים ממנו לא יתפצלו, ובדקו את הכותרות שחשובות: content type, caching, CORS.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (109, 8, 3, 'מתי למקק (mock) תלות ומתי לפנות לשירות האמיתי?', 'מקקו את מה שאינכם מחזיקים ואינכם שולטים בו; בדקו את האמיתי היכן שהסיכון נמצא.', ARRAY['מקקו צדדים שלישיים, שירותים בתשלום או מוגבלי קצב, כל דבר לא דטרמיניסטי (זמן, אקראיות), ומצבי כשל שאי אפשר לזמן לפי דרישה — 500, timeout, תגובות חלקיות.', 'השתמשו בתלות האמיתית עבור השירותים שלכם בבדיקות אינטגרציה. Mock של הקוד שלכם מתרחק ממנו ומעניק ביטחון שלא הרווחתם.', 'מצב הכשל הקלאסי: הכול ממוקק, הכול ירוק, והמערכת שבורה בפרודקשן כי ה-mock קידד API שמעולם לא היה קיים. בדיקות חוזה הן התרופה.', 'הציגו את הפשרה בפשטות — mocks קונים מהירות ודטרמיניזם, תלויות אמיתיות קונות אמת — ואמרו שסוויטה טובה משלבת את שתיהן במקום לבחור צד.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (110, 8, 4, 'כתוב פונקציה שהופכת את סדר המילים במשפט. איך תבדוק אותה?', 'כתבו את שתי השורות, ואז הקדישו את הזמן למקרים ששוברים אותן.', ARRAY['`def reverse_words(s): return " ".join(reversed(s.split()))` — `split()` ללא ארגומנט מכווץ רצפי רווחים וגוזם את הקצוות, וזה בדרך כלל מה שרוצים.', 'הסבירו למה בחרתם בזה ולא ב-`s.split(" ")`, ששומר מחרוזות ריקות מרווח כפול. מה נכון תלוי בדרישה — אז שאלו מה הדרישה. מראיינים מחכים בדיוק לזה.', 'מקרים: מחרוזת ריקה, מילה אחת, רווחים מרובים בין מילים, רווחים בתחילת ובסוף המחרוזת, סימני פיסוק, תווים שאינם ASCII (עברית, אמוג’י), וקלט ארוך מאוד.', 'הוסיפו בדיקת תכונה (property test): היפוך פעמיים מחזיר את המקור אחרי נרמול רווחים, וקבוצת המילים נשמרת. תכונות תופסות קלטים שהדוגמאות שלכם לא דמיינו.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (111, 8, 5, 'איך אתה הופך פעולות כתיבה (POST/PUT) לבטוחות ל-retry?', 'הלקוח ינסה שוב. השרת אסור שיחייב פעמיים.', ARRAY['אידמפוטנטיות אומרת ש-N בקשות זהות משאירות את אותו מצב כמו אחת. PUT ו-DELETE אידמפוטנטיים מטבעם; POST לא — ובדיוק לכן הוא זקוק לעזרה.', 'המנגנון הסטנדרטי הוא idempotency key: הלקוח שולח מפתח ייחודי, השרת שומר אותו יחד עם התוצאה, ומשחזר את התגובה השמורה במקום לבצע שוב.', 'בדקו על ידי שליחת אותה בקשה פעמיים עם אותו מפתח, ובדקו שנוצר משאב אחד, שחוזר אותו גוף תגובה, ושלא ירתה תופעת לוואי כפולה — חיוב אחד, מייל אחד.', 'בדקו גם את השלילי: אותו מפתח עם גוף *שונה* חייב להידחות ולא להישחזר בשקט, ומפתחות חייבים לפוג.']::text[]);